<style>
.mofa{--ink:#172554;--line:#dbe3ec;--blue:#3b82f6;--green:#047857;color:#334155}.mofa h1,.mofa h2{color:var(--ink)}.mofa button,.mofa a,.mofa input,.mofa select,.mofa textarea{outline-offset:3px}.mofa :focus-visible{outline:2px solid var(--blue)}.mf-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:44px;padding:9px 14px;border:1px solid var(--line);border-radius:7px;background:white;font-size:13px;font-weight:600;color:#334155}.mf-primary{background:var(--green);border-color:var(--green);color:white}.mf-btn:hover{box-shadow:0 2px 6px #17255415}.mf-input{width:100%;min-height:44px;border:1px solid #cbd5e1;border-radius:6px;padding:9px 11px;background:white;color:#1e293b;font-size:14px}.mf-label{display:block;margin-bottom:6px;font-size:13px;font-weight:600}.mf-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.mf-card{border:1px solid var(--line);border-radius:10px;background:white;padding:18px}.mf-table{width:100%;min-width:2300px;border-collapse:collapse;font-size:13px}.mf-table th{background:#eef2f7;text-align:left;color:#334155;font-weight:600;padding:13px 12px;white-space:nowrap}.mf-table td{border-bottom:.5px solid var(--line);padding:14px 12px;max-width:240px;overflow-wrap:anywhere}.mf-table tbody tr:nth-child(even){background:#f8fafc}.mf-table tbody tr:hover{background:#eff6ff}.mf-badge{display:inline-block;margin-top:5px;padding:3px 7px;border-radius:5px;font-size:11px;font-weight:600}.mf-active{background:#d1fae5;color:#065f46}.mf-expired{background:#fee2e2;color:#991b1b}.mf-expiring{background:#fef3c7;color:#92400e}.mf-processing{background:#dbeafe;color:#1e40af}.mf-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.mf-error{color:#b91c1c;font-size:12px;margin-top:4px}.mf-input[aria-invalid=true]{border-color:#ef4444}.mf-input[readonly]{background:#f1f5f9}.mf-actions{display:flex;gap:8px}.mf-actions a,.mf-actions button{min-width:44px;min-height:44px;display:grid;place-items:center;border-radius:6px}.mf-actions a:hover,.mf-actions button:hover{background:#e2e8f0}@media(max-width:1199px){.mf-grid,.mf-form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767px){.mf-grid,.mf-form-grid{grid-template-columns:1fr}}
</style>